import os
import xml.etree.ElementTree as ET

RULE_DIR = "app/rules/wazuh-ruleset/rules/"

def build_base_logtype_rule_map():
    """
    Scan all rule XMLs and map log types to rule IDs dynamically.
    Returns a dict: { log_type: [rule_id1, rule_id2, ...] }
    """
    logtype_rule_map = {}

    for filename in os.listdir(RULE_DIR):
        if not filename.endswith(".xml"):
            continue
        path = os.path.join(RULE_DIR, filename)
        try:
            tree = ET.parse(path)
            root = tree.getroot()
            for rule in root.findall("rule"):
                rule_id = rule.attrib.get("id")
                log_types = rule.attrib.get("log_type")  # sometimes in attribute
                if not log_types:
                    log_types = [lt.text for lt in rule.findall("log_type")]
                if isinstance(log_types, str):
                    log_types = [log_types]
                for lt in log_types:
                    lt = lt.lower()
                    logtype_rule_map.setdefault(lt, []).append(rule_id)
        except Exception as e:
            print(f"Failed to parse {filename}: {e}")

    return logtype_rule_map

BASE_LOGTYPE_RULE_MAP = build_base_logtype_rule_map()


def get_candidate_rules(log_type: str):
    """
    Return candidate rules for a given log type.
    Merges rules from all decoders mapped to this log type.
    Handles variations like 'other_windows', 'other_linux'.
    """
    normalized_type = log_type.lower()
    if normalized_type.startswith("other_"):
        normalized_type = normalized_type[len("other_"):]

    # Collect rule groups from all decoders matching this log type
    merged_rules = set()
    for decoder_info in DECODER_LOGTYPE_RULE_MAP.values():
        if decoder_info.get("log_type") == normalized_type:
            merged_rules.update(decoder_info.get("rule_groups", []))

    if merged_rules:
        return sorted(merged_rules)

    # fallback: use BASE_LOGTYPE_RULE_MAP for this type
    if normalized_type in BASE_LOGTYPE_RULE_MAP:
        return BASE_LOGTYPE_RULE_MAP[normalized_type]

    # final fallback: 'other'
    return BASE_LOGTYPE_RULE_MAP.get("other", ["rule_9999"])

